
import type { BuyerInstructionsConfigInput } from './BuyerInstructionsConfigInput.js';
import type { DeliveryArrivalEstimateInput } from './DeliveryArrivalEstimateInput.js';
import type { DeliveryPickupDetailsInput } from './DeliveryPickupDetailsInput.js';
import type { DeliveryPlanInput } from './DeliveryPlanInput.js';
import type { DeliveryQuoteExecutionLegResourceInput } from './DeliveryQuoteExecutionLegResourceInput.js';
import type { DeliveryRecipientRequirementInput } from './DeliveryRecipientRequirementInput.js';
import type { DeliveryShipmentDetailsInput } from './DeliveryShipmentDetailsInput.js';
import type { DeliveryWindowResourceInput } from './DeliveryWindowResourceInput.js';
import type { MoneyValueInput } from './MoneyValueInput.js';

export type DeliveryOptionProjectionInput = { "amount_money": MoneyValueInput; "arrival_estimate"?: DeliveryArrivalEstimateInput; "buyer_instructions": BuyerInstructionsConfigInput; /** Flint charge tax category. */ "charge_tax_category"?: "service_fee" | "shipping" | "delivery" | "handling" | "surcharge"; "consumed_by_delivery_selection_id"?: string; "delivery_method_id": string; "delivery_method_revision_id"?: string; "delivery_option_id"?: string; "delivery_plan": DeliveryPlanInput; "description"?: string; /** Format: int32. */ "display_position": number; /** Where this option's items leave from, one leg per origin Location. Under method_origin routing each method uses its own origin, so a pickup option leaves from the chosen store while a shipment option can leave from a warehouse. Selecting the option makes these legs the selection's execution legs. */ "execution_legs"?: Array<DeliveryQuoteExecutionLegResourceInput>; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string | globalThis.Date; "local_delivery"?: DeliveryShipmentDetailsInput; "name": string; "offered_windows"?: Array<DeliveryWindowResourceInput>; "pickup"?: DeliveryPickupDetailsInput; /** Recipient fields this option asks for. A selection can leave out required fields, but payment needs them. */ "recipient_requirements"?: Array<DeliveryRecipientRequirementInput>; "recommended": boolean; "shipment"?: DeliveryShipmentDetailsInput; "taxable": boolean; /** IANA timezone for displaying window_start_at, window_end_at, and any offered windows. Example: "America/New_York". */ "timezone"?: string; "type": "shipment" | "pickup" | "local_delivery"; /** RFC3339 timestamp. Format: date-time. */ "window_end_at"?: string | globalThis.Date; "window_pricing"?: "uniform" | "varies"; "window_selection": "none" | "offered"; /** RFC3339 timestamp. Format: date-time. */ "window_start_at"?: string | globalThis.Date; };
